pub enum Scenario {
    /// Deltas, stop reason, usage, terminator, clean EOF.
    CleanStop,
    /// Stop reason observed, then the body ends cleanly with no terminator.
    TruncatedAfterStopReason,
    /// Body ends cleanly mid-generation; no stop reason is ever observed.
    TruncatedMidGeneration,
    /// Body aborted mid-generation; no stop reason is ever observed.
    ErrorMidGeneration,
    /// Stop reason observed, then the body is aborted.
    ErrorAfterStopReason,
    /// Cancelled mid-generation; no stop reason is ever observed.
    CancelMidGeneration,
    /// Stop reason observed, then cancelled before end-of-stream.
    CancelAfterStopReason,
    /// A tool call whose name arrives split across two or more deltas.
    FragmentedToolName,
    /// One complete tool call followed by a tool-use stop reason.
    ToolCallCleanStop,
    /// A signed thinking block, then one complete tool call, then a tool-use
    /// stop reason.
    ThinkingToolCallCleanStop,
    /// Reasoning, then text, then one complete tool call, then a tool-use
    /// stop reason. Provider-neutral: any reasoning channel serves it.
    ReasoningCleanStop,
    /// Two or more complete tool calls, then a tool-use stop reason.
    ParallelToolCallCleanStop,
    /// One complete tool call with no arguments (a `{}` delta), then a
    /// tool-use stop reason.
    ZeroArgToolCallCleanStop,
}

impl Scenario {
    /// Every scenario, in table order.
    pub const ALL: &'static [Scenario] = &[
        Scenario::CleanStop,
        Scenario::TruncatedAfterStopReason,
        Scenario::TruncatedMidGeneration,
        Scenario::ErrorMidGeneration,
        Scenario::ErrorAfterStopReason,
        Scenario::CancelMidGeneration,
        Scenario::CancelAfterStopReason,
        Scenario::FragmentedToolName,
        Scenario::ToolCallCleanStop,
        Scenario::ThinkingToolCallCleanStop,
        Scenario::ReasoningCleanStop,
        Scenario::ParallelToolCallCleanStop,
        Scenario::ZeroArgToolCallCleanStop,
    ];

    /// Whether this scenario's script must let the translator observe a stop
    /// reason. Cross-checked against each subject's own declaration so a
    /// mis-transcribed fixture cannot make assertion 3 pass vacuously.
    pub fn expects_stop_reason(self) -> bool {
        matches!(
            self,
            Scenario::CleanStop
                | Scenario::TruncatedAfterStopReason
                | Scenario::ErrorAfterStopReason
                | Scenario::CancelAfterStopReason
                | Scenario::ToolCallCleanStop
                | Scenario::ThinkingToolCallCleanStop
                | Scenario::ReasoningCleanStop
                | Scenario::ParallelToolCallCleanStop
                | Scenario::ZeroArgToolCallCleanStop
        )
    }
}

/// One run of same-channel events, in wire order.
///
/// `ReasoningDelta`, `TokenDelta` and `ToolCallDelta` each map to one channel.
/// Adjacent events of one channel merge into one run.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Channel {
    /// `ReasoningDelta` events.
    Reasoning,
    /// `TokenDelta` events.
    Text,
    /// `ToolCallDelta` events.
    Tool,
}

/// A tool call that a fixture carries: its name and its complete arguments as
/// JSON text.
///
/// `args` is text, not a parsed value, so that a table of calls can be a
/// `const`. The floor parses it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ExpectedCall {
    /// The tool name of the call.
    pub name: &'static str,
    /// The complete arguments of the call, as JSON text.
    pub args: &'static str,
}

/// A contract violation, classified. Ordering matters — see `classify`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Violation {
    /// More than one `Finish` was emitted (assertion 1).
    DuplicateFinish,
    /// A `Usage` was emitted after `Finish` (assertion 2).
    UsageAfterFinish,
    /// Any other event, or an `Err`, was emitted after `Finish` (assertion 1).
    EventAfterFinish,
    /// End-of-stream after an observed stop reason emitted no `Finish`
    /// (assertion 3).
    MissingFinish,
    /// A `Finish` was emitted although no stop reason was observed
    /// (assertion 4).
    FinishOnTruncation,
    /// A `Finish` was emitted after cancellation (assertion 5).
    FinishOnCancel,
    /// A `Finish` was emitted after a mid-stream error (assertion 6).
    FinishAfterError,
    /// An event other than `Usage` followed the first `Err` (assertion 9).
    EventAfterError,
    /// A `call_id` carried a number of name-bearing deltas other than one, or
    /// the name did not match the fixture's declared tool name (assertion 7).
    ToolNameNotExactlyOnce {
        /// The call whose name emission was wrong.
        call_id: String,
        /// How many deltas for that `call_id` carried `Some(name)`.
        count: usize,
    },
    /// A `ProviderData` event named a `call_id` for which the stream carried no
    /// `ToolCallDelta` (assertion 8).
    ProviderDataUnknownCall {
        /// The `call_id` that no streamed tool call used.
        call_id: String,
    },
    /// A call's concatenated `args_delta` did not parse as JSON on a stream
    /// that carried a `Finish` (assertion 10).
    ToolArgsNotJson {
        /// The call whose arguments did not parse.
        call_id: String,
    },
    /// The stream did not produce the minimum evidence its scenario requires,
    /// so the assertions would have passed vacuously.
    InsufficientEvidence(&'static str),
    /// The terminal event carried a different `FinishReason` than the
    /// subject's fixture declares, so the bytes served are not the ones the
    /// scenario describes (spec §7.1).
    FinishReasonMismatch {
        /// What the subject's `fixture_finish_reason` declared.
        expected: FinishReason,
        /// What the stream actually emitted.
        observed: FinishReason,
    },
    /// The run order of the reasoning, text and tool channels differs from
    /// the order that the subject's fixture declares. This is a check of
    /// fidelity to the wire, not of the contract, which lets the channels
    /// interleave freely.
    ChannelOrderMismatch {
        /// What the subject's `fixture_channel_order` declared.
        expected: Vec<Channel>,
        /// The runs the stream actually emitted.
        observed: Vec<Channel>,
    },
    /// The observed tool calls, in first-seen `call_id` order, differ from
    /// the calls that the subject's fixture declares, by name or by parsed
    /// arguments. The match is by position, not by `call_id`.
    ToolCallsMismatch {
        /// What the subject's `fixture_calls` declared, as (name, arguments).
        expected: Vec<(String, serde_json::Value)>,
        /// The calls the stream actually emitted, as (name, arguments).
        observed: Vec<(String, serde_json::Value)>,
    },
    /// The stream did not terminate within the per-scenario timeout.
    Timeout,
    /// The subject's `encodes_stop_reason` disagreed with the scenario's own
    /// expectation, so its fixture does not match the script it claims.
    StopReasonDeclarationMismatch {
        /// What the scenario requires.
        expected: bool,
        /// What the subject declared.
        declared: bool,
    },
}

/// Released by the harness once it has observed the gate event, letting the
/// server send the remaining chunks.
pub struct GateHandle {
    /// Signalled by the harness; the server waits on the paired receiver.
    /// Named `tx` rather than `release` so it does not shadow the method below.
    pub(crate) tx: tokio::sync::oneshot::Sender<()>,
}

impl GateHandle {
    /// Let the server send the remaining chunks.
    ///
    /// Returns whether the server was still parked on this gate. `false` means
    /// it had already run its script to the end, so nothing was being withheld
    /// — which is how a cancellation scenario silently degrades into an ungated
    /// one, and why `assert_conforms` reads this value rather than discarding
    /// it.
    pub fn release(self) -> bool {
        self.tx.send(()).is_ok()
    }
}

/// What a subject did with a scenario.
///
/// Declining and being uncaptured are first-class outcomes carrying a mandatory
/// reason, not an `Option` a caller can silently treat as a skip. Neither is
/// served, so no floor or assertion runs for them. The two are not
/// interchangeable: [`Outcome::Declined`] must match [`DECLINED`], and
/// [`Outcome::Uncaptured`] must match [`UNCAPTURED`].
pub enum Outcome {
    /// The subject served the scenario.
    Served {
        /// The stream returned by the subject's `Model::invoke`.
        stream: BoxStream<'static, Result<ModelEvent, ModelError>>,
        /// Present only for the cancellation scenarios.
        gate: Option<GateHandle>,
    },
    /// The wire shape cannot physically occur for this provider. The reason is
    /// printed in the report and must match the pinned decline set.
    Declined(&'static str),
    /// The wire shape can occur for this provider, and a capture alone would
    /// let the subject serve it, but no fixture that meets the provenance rule
    /// exists. The reason must match the pinned [`UNCAPTURED`] table.
    Uncaptured(&'static str),
}

/// One provider backend under test.
#[async_trait::async_trait]
pub trait StreamUnderTest {
    /// Stable subject name, e.g. `"openai/chat"`. Used in failure output and to
    /// match rows in the pinned decline set.
    fn name(&self) -> &'static str;

    /// Whether this subject's fixture for `scenario` encodes a stop reason.
    /// Cross-checked against the scenario's own expectation.
    fn encodes_stop_reason(&self, scenario: Scenario) -> bool;

    /// The tool name this subject's tool-call fixtures declare.
    fn fixture_tool_name(&self) -> &'static str;

    /// The `FinishReason` this subject's fixture for `scenario` declares, or
    /// `None` for scenarios that must not produce a `Finish` at all.
    ///
    /// Exactly seven scenarios end with a `Finish`, and the floor checks this
    /// value for all seven: `CleanStop`, `ToolCallCleanStop`,
    /// `ThinkingToolCallCleanStop`, `ReasoningCleanStop`,
    /// `ParallelToolCallCleanStop`, `ZeroArgToolCallCleanStop`, and
    /// `TruncatedAfterStopReason`, where
    /// assertion 3 requires the buffered stop reason to be flushed at
    /// end-of-stream. Every other scenario must return `None` — a cancelled or
    /// errored stream withholds `Finish`, and a truncation with no stop reason
    /// observed never had one to emit.
    ///
    /// The seven differ in one way only: for the six clean stops a missing
    /// `Finish` fails the floor, whereas for `TruncatedAfterStopReason` it is
    /// `classify`'s `MissingFinish` (the SMA-531 shape). Either way, a `Finish`
    /// that *is* emitted must carry what this method declares.
    ///
    /// Declared per subject rather than inferred suite-side because only the
    /// fixture knows what its bytes encode: a checker that assumed
    /// `CleanStop` ⇒ `Stop` would silently accept a fixture that had been
    /// transcribed with the wrong stop reason.
    fn fixture_finish_reason(&self, scenario: Scenario) -> Option<FinishReason>;

    /// The run order of the reasoning, text and tool channels in this
    /// subject's fixture for `scenario`, read from the capture. `None` means
    /// that the subject makes no claim.
    ///
    /// `ReasoningCleanStop` requires `Some(..)`. For any scenario that returns
    /// `Some(..)`, the floor compares the observed runs with it.
    fn fixture_channel_order(&self, scenario: Scenario) -> Option<&'static [Channel]>;

    /// The tool calls that this subject's fixture for `scenario` carries, in
    /// wire order, read from the capture.
    ///
    /// `ReasoningCleanStop`, `ParallelToolCallCleanStop` and
    /// `ZeroArgToolCallCleanStop` require a non-empty list. Every other
    /// scenario returns `&[]`. For a scenario with a non-empty list, the floor reads the declared tool names from it instead
    /// of from [`StreamUnderTest::fixture_tool_name`], and it compares the
    /// observed calls with it by name and by parsed arguments.
    fn fixture_calls(&self, scenario: Scenario) -> &'static [ExpectedCall];

    /// Serve `scenario` and return the subject's `Model::invoke` stream.
    async fn stream(&self, scenario: Scenario, cancel: CancellationToken) -> Outcome;
}

/// How long one scenario's drain may run before the suite gives up on it.
///
/// A subject whose stream never terminates is a real bug this suite should
/// catch, and without a bound it would hang `cargo test` rather than fail it.
/// Generous on purpose: it is only ever reached on failure, so it costs nothing
/// on a green run.
const DRAIN_TIMEOUT: Duration = Duration::from_secs(10);

/// How long a gated stream must stay silent before the harness accepts that the
/// server is parked on the gate and fires cancellation.
///
/// **Why quiescence and not a named gate edge.** The design spec's §6.1 has the
/// harness block on a specific event — a `TokenDelta` for `CancelMidGeneration`,
/// the `Usage` the fixture places after the stop-reason chunk for
/// `CancelAfterStopReason`. That does not survive contact with Anthropic, which
/// emits a `Usage` from `message_start` (`anthropic/stream.rs:79`): "cancel on
/// the first `Usage`" would fire before any stop reason was buffered, and
/// `CancelAfterStopReason` would silently degrade into `CancelMidGeneration` for
/// that subject. Silence is subject-independent, and — unlike an event
/// predicate — is itself positive evidence that the server is withholding.
///
/// **What a slow machine does to it.** Firing *late* (the harness task is
/// descheduled, so the window elapses later in wall-clock terms) is harmless:
/// the server is parked either way and nothing else is in flight. Firing
/// *early* is the dangerous direction, and the timer arms twice with different
/// stakes:
///
/// - **Between two events.** Needs two consecutive pre-gate chunks more than
///   this far apart, which the server does not produce: `feed` pushes every
///   pre-gate chunk into an unbounded channel with no await between them, so
///   they reach the socket back-to-back over loopback. If it ever did happen,
///   the consequence is a weaker test — cancellation at an earlier truncation
///   point — not a red run.
/// - **Before the first event**, which is the arming that can actually fail a
///   run. It covers connect, request, response head and first chunk, with
///   nothing yet consumed. Should *that* window elapse, the token fires having
///   collected nothing and the scenario dies on the "no TokenDelta" floor — a
///   spurious failure, not a weaker test. Sub-millisecond on loopback, but it
///   is the first thing to suspect behind an intermittent cancel-scenario
///   failure, ahead of anything in the provider.
///
/// The `server_was_parked` evidence below is unaffected in every case.
const GATE_QUIESCENCE: Duration = Duration::from_millis(400);

/// Run every [`Scenario`] against `subject` and panic on the first thing that
/// does not hold.
///
/// Three guards run in order for each served scenario, and each exists because
/// of a specific way this suite could go quietly useless:
///
/// 1. **The stop-reason declaration is cross-checked.** Assertions 3 and 4 are
///    conditioned on whether a stop reason was observed, and that cannot be
///    inferred from the emitted events — a provider wrongly suppressing
///    `Finish` looks identical to one that correctly never saw a stop reason.
/// 2. **The positive-evidence floors run before the assertions.** A stream that
///    emits nothing satisfies "ends with `Finish`" trivially, so a miswired
///    adapter serving the wrong fixture would otherwise pass every assertion by
///    producing nothing at all.
/// 3. **Then, and only then, the events are classified** by the crate's
///    `classify` function.
///
/// Afterwards the observed declines and uncaptured pairs are compared against
/// the pinned [`DECLINED`] and [`UNCAPTURED`] tables in both directions.
pub async fn assert_conforms(subject: &impl StreamUnderTest) {
    assert_conforms_with(subject, DECLINED, UNCAPTURED).await;
}

/// [`assert_conforms`] against explicit pinned tables, so the unit tests can
/// drive the stale-row direction without a real row.
async fn assert_conforms_with(
    subject: &impl StreamUnderTest,
    pinned_declined: &[(&str, Scenario, &str)],
    pinned_uncaptured: &[(&str, Scenario, &str, &str)],
) {
    let name = subject.name();
    let mut declined: Vec<(Scenario, &'static str)> = Vec::new();
    let mut uncaptured: Vec<(Scenario, &'static str)> = Vec::new();

    for &scenario in Scenario::ALL {
        let cancel = CancellationToken::new();
        let (stream, gate) = match subject.stream(scenario, cancel.clone()).await {
            Outcome::Declined(reason) => {
                declined.push((scenario, reason));
                continue;
            }
            Outcome::Uncaptured(reason) => {
                uncaptured.push((scenario, reason));
                continue;
            }
            Outcome::Served { stream, gate } => (stream, gate),
        };

        let declared = subject.encodes_stop_reason(scenario);
        let expected = scenario.expects_stop_reason();
        if declared != expected {
            fail(
                name,
                scenario,
                &Violation::StopReasonDeclarationMismatch { expected, declared },
                "the subject's fixture does not encode what this scenario requires, so \
                 assertions 3 and 4 would be checked against the wrong condition",
            );
        }

        let cancelled = is_cancel_scenario(scenario);
        if cancelled && gate.is_none() {
            fail(
                name,
                scenario,
                &Violation::InsufficientEvidence(
                    "a cancellation scenario was served without a gate, so the whole body was \
                     already on its way and cancellation could not truncate anything",
                ),
                "give the script a `gate_after` and hand the `GateHandle` back in \
                 `Outcome::Served`",
            );
        }

        let Ok(drained) =
            tokio::time::timeout(DRAIN_TIMEOUT, drain(stream, gate, scenario, cancel)).await
        else {
            fail(
                name,
                scenario,
                &Violation::Timeout,
                "the stream never ended. For a cancellation scenario, check that the driver \
                 selects on the cancellation token while awaiting the next chunk; otherwise \
                 check that the script's ending actually closes the body",
            );
        };

        if let Some(violation) = floor_violation(
            scenario,
            &drained.events,
            subject.fixture_tool_name(),
            subject.fixture_finish_reason(scenario),
            subject.fixture_channel_order(scenario),
            subject.fixture_calls(scenario),
        ) {
            fail(
                name,
                scenario,
                &violation,
                &format!("observed: {}", summarise(&drained.events)),
            );
        }

        if let Some(violation) = drained.cancel_violation() {
            fail(
                name,
                scenario,
                &violation,
                &format!("observed: {}", summarise(&drained.events)),
            );
        }

        if let Some(violation) = classify(&drained.events, scenario, cancelled) {
            fail(
                name,
                scenario,
                &violation,
                &format!("observed: {}", summarise(&drained.events)),
            );
        }
    }

    let expected_declined: Vec<(Scenario, &str)> = pinned_declined
        .iter()
        .filter(|(n, _, _)| *n == name)
        .map(|(_, sc, r)| (*sc, *r))
        .collect();
    let expected_uncaptured: Vec<(Scenario, &str)> = pinned_uncaptured
        .iter()
        .filter(|(n, _, _, _)| *n == name)
        .map(|(_, sc, r, _)| (*sc, *r))
        .collect();

    let mut problems = pinned_problems(PinnedKind::Declined, &declined, &expected_declined);
    problems.extend(pinned_problems(
        PinnedKind::Uncaptured,
        &uncaptured,
        &expected_uncaptured,
    ));
    assert!(
        problems.is_empty(),
        "conformance: {name} — the observed decline or uncaptured set does not match the \
         pinned DECLINED or UNCAPTURED table (SMA-533 design §6.2, SMA-567 design §6.4):\n{}",
        problems.join("\n")
    );
}

/// Whether `scenario` cancels the stream part-way through.
fn is_cancel_scenario(scenario: Scenario) -> bool {
    matches!(
        scenario,
        Scenario::CancelMidGeneration | Scenario::CancelAfterStopReason
    )
}

/// Everything one scenario's drain observed.
struct Drained {
    /// The events the subject's stream produced, in order.
    events: Vec<Result<ModelEvent, ModelError>>,
    /// Present only for a cancellation scenario.
    cancel: Option<CancelEvidence>,
}

/// Proof that a cancellation scenario actually cancelled something.
///
/// Dropping a [`GateHandle`] releases the body, so a cancellation scenario can
/// silently degrade into an ungated one — the whole script plays out, the
/// stream ends on its own, and the assertions pass without cancellation ever
/// having been exercised. Both fields below are recorded so that degradation
/// fails loudly instead.
struct CancelEvidence {

content.content:
660	/// `CleanStop`.
661	///
662	/// `ReasoningCleanStop` has two more floors: at least one `ReasoningDelta`,
663	/// and a declared channel order. When a subject declares a channel order
664	/// (`channel_order`), the observed runs of `ReasoningDelta`, `TokenDelta` and
665	/// `ToolCallDelta` must equal it, or the result is `ChannelOrderMismatch`.
666	/// That check is about fidelity to the wire order, not about the contract: the
667	/// contract lets the three channels interleave freely
668	/// (`core/src/model.rs:56-57`). An empty delta still counts as a run, because a
669	/// real wire can carry one and the translator passes it on.
670	///
671	/// Declared calls (`calls`, from `fixture_calls`). For a scenario with a
672	/// non-empty list, the "declared name is present" floor requires every
673	/// declared name instead of the one `tool_name`. The observed calls, in
674	/// first-seen `call_id` order, must then equal the declared calls by name and
675	/// by parsed arguments, or the result is `ToolCallsMismatch`. The match is by
676	/// position, not by `call_id`, because a subject cannot always declare the ids
677	/// that its translator makes. A call whose arguments do not parse is skipped,
678	/// so that assertion 10 reports it under its exact `call_id`.
679	/// `ReasoningCleanStop`, `ParallelToolCallCleanStop` and
680	/// `ZeroArgToolCallCleanStop` must declare a non-empty list.
681	/// `ParallelToolCallCleanStop` also requires two or more distinct non-blank
682	/// `call_id`s.
683	///
684	/// The ticket proposed a floor that required `Usage` and `Finish` to be
685	/// adjacent and terminal in `CleanStop`. That floor was replaced. It cannot see
686	/// the Bedrock `metadata`/`messageStop` swap, because both orders give the same
687	/// `Usage, Finish` event sequence. It cannot see the SMA-522 fixture mistake,
688	/// because `openai/chat` and `litellm` buffer `Finish` to end-of-stream. All
689	/// six subjects already passed it. The core contract also lets `Usage` appear
690	/// anywhere (design spec section 3.2).
691	///
692	/// The `FinishReason` check also lives here rather than in `classify`, and
693	/// must: `classify` has no fixture knowledge and its signature is fixed, while
694	/// the reason a `Finish` should carry is exactly a property of the bytes the
695	/// subject transcribed.
696	fn floor_violation(
697	    scenario: Scenario,
698	    events: &[Result<ModelEvent, ModelError>],
699	    tool_name: &str,
700	    finish_reason: Option<FinishReason>,
701	    channel_order: Option<&[Channel]>,
702	    calls: &[ExpectedCall],
703	) -> Option<Violation> {
704	    match scenario {
705	        Scenario::CleanStop
706	        | Scenario::TruncatedAfterStopReason
707	        | Scenario::TruncatedMidGeneration
708	        | Scenario::ErrorMidGeneration
709	        | Scenario::ErrorAfterStopReason
710	        | Scenario::CancelMidGeneration
711	        | Scenario::CancelAfterStopReason => {
712	            if !events
713	                .iter()
714	                .any(|e| matches!(e, Ok(ModelEvent::TokenDelta { .. })))
715	            {
716	                return Some(Violation::InsufficientEvidence(
717	                    "no TokenDelta: a stream that emitted no text passes every ordering \
718	                     assertion vacuously",
719	                ));
720	            }
721	        }
722	        Scenario::FragmentedToolName
723	        | Scenario::ToolCallCleanStop
724	        | Scenario::ThinkingToolCallCleanStop
725	        | Scenario::ReasoningCleanStop
726	        | Scenario::ParallelToolCallCleanStop
727	        | Scenario::ZeroArgToolCallCleanStop => {
728	            if !events
729	                .iter()
730	                .any(|e| matches!(e, Ok(ModelEvent::ToolCallDelta { .. })))
731	            {
732	                return Some(Violation::InsufficientEvidence(
733	                    "no ToolCallDelta: a tool scenario that emitted no tool call passes \
734	                     assertion 7 vacuously",
735	                ));
736	            }
737	            // With declared calls, every declared name must be present.
738	            // Without them, the one `fixture_tool_name` must be.
739	            let declared_names: Vec<&str> = if calls.is_empty() {
740	                vec![tool_name]
741	            } else {
742	                calls.iter().map(|call| call.name).collect()
743	            };
744	            let named = |wanted: &str| {
745	                events.iter().any(|e| {
746	                    matches!(e, Ok(ModelEvent::ToolCallDelta { name: Some(name), .. }) if name == wanted)
747	                })
748	            };
749	            if !declared_names.into_iter().all(named) {
750	                return Some(Violation::InsufficientEvidence(
751	                    "no ToolCallDelta carried the tool name this subject declares, so the \
752	                     fixture served is not the one the scenario describes",
753	                ));
754	            }
755	        }
756	    }
757	
758	    if matches!(
759	        scenario,
760	        Scenario::ReasoningCleanStop
761	            | Scenario::ParallelToolCallCleanStop
762	            | Scenario::ZeroArgToolCallCleanStop
763	    ) && calls.is_empty()
764	    {
765	        return Some(Violation::InsufficientEvidence(
766	            "the subject declares no calls for a scenario that compares its calls, so the \
767	             call comparison would compare nothing",
768	        ));
769	    }
770	
771	    if matches!(scenario, Scenario::ParallelToolCallCleanStop) {
772	        let mut ids: Vec<&str> = Vec::new();
773	        for event in events {
774	            if let Ok(ModelEvent::ToolCallDelta { call_id, .. }) = event {
775	                if !call_id.trim().is_empty() && !ids.contains(&call_id.as_str()) {
776	                    ids.push(call_id);
777	                }
778	            }
779	        }
780	        if ids.len() < 2 {
781	            return Some(Violation::InsufficientEvidence(
782	                "fewer than two distinct non-blank call_ids: a parallel scenario that \
783	                 streamed one call did not serve parallel calls",
784	            ));
785	        }
786	    }
787	
788	    if !calls.is_empty() {
789	        if let Some(violation) = calls_mismatch(events, calls) {
790	            return Some(violation);
791	        }
792	    }
793	
794	    // Assertion 8 checks every call-scoped `ProviderData` against the streamed
795	    // calls. With none in the stream it passes with no evidence, so this
796	    // scenario requires at least one.
797	    if matches!(scenario, Scenario::ThinkingToolCallCleanStop)
798	        && !events.iter().any(|e| {
799	            matches!(
800	                e,
801	                Ok(ModelEvent::ProviderData {
802	                    call_id: Some(_),
803	                    ..
804	                })
805	            )
806	        })
807	    {
808	        return Some(Violation::InsufficientEvidence(
809	            "no call-scoped ProviderData: assertion 8 would pass vacuously",
810	        ));
811	    }
812	
