817	        {
818	            return Some(Violation::InsufficientEvidence(
819	                "no ReasoningDelta: a reasoning scenario that emitted no reasoning passes the \
820	                 channel-order check with no reasoning run in it",
821	            ));
822	        }
823	        if channel_order.is_none() {
824	            return Some(Violation::InsufficientEvidence(
825	                "the subject declares no channel order for a reasoning scenario, so the \
826	                 channel-order check would compare nothing",
827	            ));
828	        }
