947	        ));
948	    }
949	
950	    // Every `CleanStop` script carries usage. A stream without one did not
951	    // serve the scenario's bytes.
952	    if matches!(scenario, Scenario::CleanStop)
953	        && !events
954	            .iter()
955	            .any(|e| matches!(e, Ok(ModelEvent::Usage { .. })))
956	    {
957	        return Some(Violation::InsufficientEvidence(
958	            "no Usage in CleanStop: every CleanStop script carries usage, so a stream \
959	             without one did not serve the scenario's bytes",
960	        ));
961	    }
962	
963	    if matches!(
964	        scenario,
965	        Scenario::ErrorMidGeneration | Scenario::ErrorAfterStopReason
966	    ) && !events.iter().any(Result::is_err)
967	    {
968	        return Some(Violation::InsufficientEvidence(
969	            "an error scenario must yield an Err: none means the aborted body was read as a \
970	             clean end-of-stream",
971	        ));
972	    }
