999	        {
1000	            let at = match groups.iter().position(|(id, _, _)| id == call_id) {
1001	                Some(at) => at,
1002	                None => {
1003	                    groups.push((call_id, None, String::new()));
1004	                    groups.len() - 1
1005	                }
1006	            };
1007	            let group = &mut groups[at];
1008	            if group.1.is_none() {
1009	                group.1 = name.as_deref();
1010	            }
1011	            group.2.push_str(args_delta);
1012	        }
1013	    }
1014	
1015	    let expected: Vec<(String, serde_json::Value)> = calls
1016	        .iter()
1017	        .map(|call| {
1018	            let args = serde_json::from_str(call.args).unwrap_or_else(|err| {
1019	                panic!(
1020	                    "the declared arguments of {:?} are not JSON ({err}): {:?}",
1021	                    call.name, call.args
1022	                )
1023	            });
1024	            (call.name.to_owned(), args)
1025	        })
1026	        .collect();
