1028	    // `None` marks a call whose arguments do not parse.
1029	    let observed: Vec<(String, Option<serde_json::Value>)> = groups
1030	        .into_iter()
1031	        .map(|(_, name, args)| {
1032	            let source = if args.trim().is_empty() {
1033	                "{}"
1034	            } else {
1035	                args.as_str()
1036	            };
