1070	    for event in events {
1071	        let channel = match event {
1072	            Ok(ModelEvent::ReasoningDelta { .. }) => Channel::Reasoning,
1073	            Ok(ModelEvent::TokenDelta { .. }) => Channel::Text,
1074	            Ok(ModelEvent::ToolCallDelta { .. }) => Channel::Tool,
