247	    /// positions of each text block and each `tool_use` block.
248	    fn stop_block(&mut self, index: u32, out: &mut Vec<Result<ModelEvent, ModelError>>) {
249	        // No event can follow `Finish`, so a block stop after the terminal
250	        // event gives no provider data.
