306	    /// Emit a valid thinking block, then every position that waits for it.
307	    fn keep_block(
308	        &mut self,
309	        index: u32,
310	        kind: &str,
311	        block: ThinkingBlock,
312	        out: &mut Vec<Result<ModelEvent, ModelError>>,
313	    ) {
314	        if !block.is_valid() {
315	            tracing::debug!(
316	                target: "paigasus::anthropic::stream",
