339	    /// Flush a stop reason buffered from `message_delta` when the response
340	    /// body ends cleanly before `message_stop` arrived.
341	    ///
342	    /// Returns `None` when a terminal event was already emitted — the
343	    /// well-formed path, where `message_stop` drained the buffer — or when no
344	    /// stop reason was ever observed. A stream that ended *before*
345	    /// `message_delta` is never reported as a clean `Stop`; one that ended
346	    /// *after* it is, because `message_delta`'s `stop_reason` is the model's
347	    /// own authoritative decision and `message_stop` is only a frame
348	    /// terminator.
349	    ///
350	    /// `terminal_emitted` — not `stop_reason` being `Some` — is the guard.
351	    /// A second `message_delta` can re-arm the buffer after `message_stop`
352	    /// already emitted, and that must not produce a second terminal event.
353	    ///
354	    /// **Clean-EOF path only.** Never call this on the cancellation or
355	    /// transport-error paths — see `model.rs`.
356	    pub(crate) fn finish(&mut self) -> Option<Result<ModelEvent, ModelError>> {
357	        if self.terminal_emitted {
358	            return None;
359	        }
360	        let reason = self.stop_reason.take()?;
361	        self.terminal_emitted = true;
362	        tracing::warn!(
363	            target: "paigasus::anthropic::stream",
364	            stop_reason = %reason,
365	            "stream body ended without message_stop; flushing buffered stop reason",
366	        );
367	        Some(self.finish_or_error(&reason))
368	    }
