370	    fn finish_or_error(&self, reason: &str) -> Result<ModelEvent, ModelError> {
371	        match reason {
372	            "end_turn" | "stop_sequence" => Ok(ModelEvent::Finish {
373	                reason: FinishReason::Stop,
374	            }),
375	            "max_tokens" => Ok(ModelEvent::Finish {
376	                reason: FinishReason::Length,
377	            }),
378	            "tool_use" => {
379	                if self.synthesizing_output && !self.other_tool_fired {
380	                    Ok(ModelEvent::Finish {
381	                        reason: FinishReason::Stop,
382	                    })
383	                } else if self.synthesizing_output && self.other_tool_fired {
384	                    Err(ModelError::Other(anyhow::anyhow!(
385	                        "structured output: model fired both a real tool and the synthesized output tool"
386	                    )))
387	                } else {
388	                    Ok(ModelEvent::Finish {
389	                        reason: FinishReason::ToolCalls,
390	                    })
391	                }
392	            }
393	            "refusal" => Err(ModelError::Refused {
394	                reason: "model refused".to_owned(),
395	            }),
396	            other => Ok(ModelEvent::Finish {
397	                reason: FinishReason::Other(other.to_owned()),
398	            }),
399	        }
400	    }
