395	    fn handle_tool_call(
396	        &mut self,
397	        tc: &ToolCallChunk,
398	        pos: usize,
399	        any_explicit_index: bool,
400	        out: &mut Vec<ModelEvent>,
401	    ) {
402	        // A blank `id` is not an identity, so it must not become `Key::Id("")`
403	        // — two such entries would share one slot and merge into a single
404	        // call. Filtering it out here sends the delta to the same arms that
405	        // handle an absent id: positional keying, or the loud skip when
406	        // another entry in this array carries an explicit index. Registration
407	        // into `tool_calls` below still reads `tc.id` directly, so a blank id
408	        // that reaches it is still recorded and still resolves to `""`. An
409	        // entry taking the ambiguity skip returns before that point, so it is
410	        // neither registered nor canonicalized (SMA-616).
411	        let key = match (tc.index, tc.id.as_deref().filter(|id| !id.is_empty())) {
412	            (Some(i), _) => Key::Index(i),
413	            (None, Some(id)) => Key::Id(id.to_owned()),
414	            (None, None) if any_explicit_index => {
415	                // A synthesized positional key would risk colliding with a
416	                // genuine explicit `index` elsewhere in this same array
417	                // (e.g. entry 0 explicitly `index: 1`, entry 1 has neither
418	                // — pos 1 would collide with `Key::Index(1)`). That mixes
419	                // two distinct calls into one and corrupts both, which is
420	                // worse than dropping this entry, so skip it loudly.
421	                tracing::warn!(
422	                    target: "paigasus::litellm::stream",
423	                    pos,
424	                    "tool-call delta at this position has neither index nor id, and \
425	                     another entry in the same array carries an explicit index; \
426	                     skipping to avoid a key collision"
427	                );
428	                return;
429	            }
430	            (None, None) => {
431	                tracing::debug!(
432	                    target: "paigasus::litellm::stream",
433	                    pos,
434	                    "tool-call delta has neither index nor id; correlating by position"
435	                );
436	                Key::Index(pos as u32)
437	            }
438	        };
