440	        // Both signals test the effective fragment, so a backend sending
441	        // `"name": ""` behaves like one omitting the field.
442	        let name_frag = tc
443	            .function
444	            .as_ref()
445	            .and_then(|f| f.name.as_deref())
446	            .unwrap_or("");
