31	fn collect_defs(root: &Value) -> Map<String, Value> {
32	    let mut out = Map::new();
33	    for key in ["$defs", "definitions"] {
34	        if let Some(Value::Object(m)) = root.get(key) {
35	            for (k, v) in m {
36	                out.insert(k.clone(), v.clone());
37	            }
38	        }
39	    }
40	    out
41	}
