    assert_eq!(
        violation,
        Some(Violation::ToolCallsMismatch {
            expected: vec![(
                crate::fakes::ZERO_ARG_TOOL_NAME.to_owned(),
                serde_json::json!({})
            )],
            observed: vec![(
                crate::fakes::ZERO_ARG_TOOL_NAME.to_owned(),
                serde_json::json!({ "tz": "UTC" })
            )],
        })
    );
}

